mapper.select:
select cc.class_id, cc.course_id, cc.teacher_id, cc.term_id, t.term_name, u.nick_name as teacher_name, cc.class_time, cc.location, cc.capacity, cc.selected_count, cc.status, c.course_name, c.course_code, c.credit_hours, e.enrollment_id, e.status as enrollment_status, e.grade_status, e.grade from course_class cc left join course c on cc.course_id = c.course_id left join term t on cc.term_id = t.term_id left join sys_user u on u.user_id = cc.teacher_id left join enrollment e on e.class_id = cc.class_id and e.student_id = #{studentId} and e.status = 'ENROLLED' where cc.status = 1
and cc.term_id = #{termId}
and c.course_name like concat('%', #{courseName}, '%')
order by cc.class_id asc limit #{offset}, #{pageSize}

select count(1) from course_class cc left join course c on cc.course_id = c.course_id where cc.status = 1
and cc.term_id = #{termId}
and c.course_name like concat('%', #{courseName}, '%')

mapper.update:
update course_class
set selected_count = case when selected_count > 0 then selected_count - 1 else 0 end
where class_id = #{classId}

mapper.select:
select cc.class_id, cc.course_id, cc.teacher_id, cc.term_id, cc.class_time, cc.location, cc.capacity, cc.selected_count, cc.status, c.course_name, c.course_code, c.credit_hours, t.term_name, (SELECT COUNT(*) FROM enrollment e WHERE e.class_id = cc.class_id AND e.status = 'ENROLLED') as student_count from course_class cc left join course c on cc.course_id = c.course_id left join term t on cc.term_id = t.term_id where cc.teacher_id = #{teacherId}
and cc.term_id = #{termId}
order by cc.term_id desc, cc.class_id asc
